import{z as i,x as l,o as e,c as s,q as A,j as o,D as a,d as n,s as t,S as r}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"经济计算的规模化","description":"","frontmatter":{"title":"经济计算的规模化","date":"2026-09-18T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/ec-scaling-computation.md","filePath":"econ/ec-scaling-computation.md","lastUpdated":1791063341000}'),c={name:"econ/ec-scaling-computation.md"};function d(p,E,C,D,m,h){const B=l("Mermaid");return e(),s("div",null,[E[2]||(E[2]=A('<h1 id="经济计算的规模化" tabindex="-1">经济计算的规模化 <a class="header-anchor" href="#经济计算的规模化" aria-label="Permalink to &quot;经济计算的规模化&quot;">​</a></h1><div class="epigraph"><p>数据变大之后，缺的从来不是统计理论，而是把既有估计量搬到这个规模上的工程。</p><footer>—— 据 Varian, Big Data: New Tricks for Econometrics, JEP 2014 整理</footer></div><p><a href="/econ/ec-reproducible-computing">上一课</a>把计算环境钉成可复现的闭包；这一课把闭包放到更大的数据与更重的数值上。问题不是「怎么用集群」，而是先回答两问：这份工作真的需要规模化吗？需要的话，瓶颈在哪一层？</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>经济计算的「大」有三种，瓶颈各不相同。宽：行政面板千万个体乘数十年，吃内存布局与顺序 I/O——扫描与分组是常态运算，随机访问是灾难。高频：逐笔价格与逐笔成交，吃流式处理与时间对齐。重数值：结构估计的内层不动点、动态规划的值函数迭代、贝叶斯的链抽样，吃浮点循环与收敛判据，数据本身可能很小。三类混谈的代价是错配：把单机向量化就能完成的横截面回归搬上集群，工期翻倍；把内层不动点的瓶颈归咎于机器不够大，加节点毫无改善。<span class="marginnote">直觉类比：三种「大」像三种活——「宽」是搬一张超长的桌子，门太窄只能拆开顺着搬（顺序扫描）；「高频」是接一根不停流的水管，得边流边处理；「重数值」是解一道要反复试的谜题，纸只有一页，难在算得深，不在纸大。</span></p><h3 id="单机阶梯与瓶颈定位" tabindex="-1">单机阶梯与瓶颈定位 <a class="header-anchor" href="#单机阶梯与瓶颈定位" aria-label="Permalink to &quot;单机阶梯与瓶颈定位&quot;">​</a></h3><p><span class="marginnote">BLP 型结构估计（<a href="/econ/se-blp-deep">BLP 需求</a>）的时间几乎全花在内层：给定非线性参数，份额与价格要迭代到不动点，外层才轮到矩条件。把内层雅可比解析化、把不动点结果缓存复用，常比换更大的机器省一个数量级——这是 Berry, Levinsohn and Pakes 1995 以来人尽皆知却常被忘的账。</span></p><p>阶梯自下而上。向量化把循环换成矩阵运算，是第一倍数。<span class="marginnote">数字实例：对一千万个数求和，写成 for 循环要解释器逐个执行千万次，向量化后整块交给底层连续内存运算，常快一到两个数量级——第一档都不爬就谈上集群，是这套阶梯最常见的浪费。</span>列式存储与分区把「宽」变成顺序扫描。多核并行吃掉天然独立的部分——<a href="/econ/bootstrap-econ">bootstrap</a> 的重抽样、参数网格的格子、模拟矩的重复抽样——这些彼此独立的活不必分布式。集群只在前三档都不够时上，语义是分组聚合与逐组估计，不是把回归「分布化」。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2>',9)),(e(),o(r,null,{default:a(()=>[t(B,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20FORM%5B%22%E6%95%B0%E6%8D%AE%E5%BD%A2%E6%80%81%3A%20%E5%AE%BD%2F%E9%AB%98%E9%A2%91%2F%E9%87%8D%E6%95%B0%E5%80%BC%22%5D%20--%3E%20BTL%7B%22%E7%93%B6%E9%A2%88%E5%AE%9A%E4%BD%8D%22%7D%0A%20%20BTL%20--%3E%7C%22%E5%AE%BD%3A%20I%2FO%20%E4%B8%8E%E6%89%AB%E6%8F%8F%22%7C%20COL%5B%22%E5%88%97%E5%AD%98%2F%E5%88%86%E5%8C%BA%2F%E5%90%91%E9%87%8F%E5%8C%96%22%5D%0A%20%20BTL%20--%3E%7C%22%E9%AB%98%E9%A2%91%3A%20%E6%B5%81%E4%B8%8E%E5%AF%B9%E9%BD%90%22%7C%20STREAM%5B%22%E6%B5%81%E5%BC%8F%E5%A4%84%E7%90%86%2F%E6%97%B6%E9%97%B4%E5%AF%B9%E9%BD%90%22%5D%0A%20%20BTL%20--%3E%7C%22%E9%87%8D%E6%95%B0%E5%80%BC%3A%20%E6%B5%AE%E7%82%B9%E5%BE%AA%E7%8E%AF%22%7C%20NUM%5B%22%E8%A7%A3%E6%9E%90%E9%9B%85%E5%8F%AF%E6%AF%94%2F%E7%BC%93%E5%AD%98%2F%E5%AE%B9%E5%B7%AE%22%5D%0A%20%20COL%20--%3E%20PAR%5B%22%E5%A4%9A%E6%A0%B8%E5%B9%B6%E8%A1%8C%3A%20%E7%8B%AC%E7%AB%8B%E9%87%8D%E6%8A%BD%E6%A0%B7%E4%B8%8E%E7%BD%91%E6%A0%BC%22%5D%0A%20%20STREAM%20--%3E%20PAR%0A%20%20NUM%20--%3E%20PAR%0A%20%20PAR%20--%3E%20CLU%7B%22%E8%BF%98%E4%B8%8D%E5%A4%9F%3F%22%7D%0A%20%20CLU%20--%3E%7C%22%E6%98%AF%22%7C%20SPARK%5B%22%E9%9B%86%E7%BE%A4%3A%20%E5%88%86%E7%BB%84%E8%81%9A%E5%90%88%E8%AF%AD%E4%B9%89%22%5D%0A%20%20CLU%20--%3E%7C%22%E5%90%A6%22%7C%20DONE%5B%22%E5%8D%95%E6%9C%BA%E6%94%B6%E5%B7%A5%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[n(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=A('<p>实验管理随规模成为一等公民：参数扫描要有成本预算与断点续跑，每个格子的结果连同种子按<a href="/econ/ec-reproducible-computing">上一课</a>的复现包归档——规模一大，丢一个格子等于丢一条结论，找不回来的那种。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>规模化改变成本结构，不改变统计逻辑。大 \\(N\\) 压抽样方差，不碰偏差：覆盖偏与选择偏仍是<a href="/econ/ec-bigdata-survey-fusion">融合课</a>的管辖，规模只是让偏的置信区间变窄——把偏得更自信。<span class="marginnote">常见误区：「数据大所以结论准」。大样本只让抽样误差变小；如果样本本身漏了某一群人，多出来的数据全是同一群人的重复——偏差原样保留，你只是更自信地错着。</span>数值层同理：收敛容差是模型风险的一部分，容差放得太松，外层矩条件在一个未收敛的解上求值，梯度与标准误全是错的；这是<a href="/econ/value-function-iteration">值函数迭代</a>与<a href="/econ/se-smm">模拟矩方法</a>讲过的纪律在规模化语境下的重申。Athey 2018 给这层的总结算：机器学习的可扩展性把过去因计算而不可行的问题——异质效应的搜索、政策函数的估计——变成常规作业，但识别约束一条没少。</p><p>容差这条线值得单独画清楚：内层的松紧如何一路污染外层的推断。</p>',4)),(e(),o(r,null,{default:a(()=>[t(B,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20IN%5B%22%E5%86%85%E5%B1%82%E4%B8%8D%E5%8A%A8%E7%82%B9%E8%BF%AD%E4%BB%A3%22%5D%20--%3E%20T%7B%22%E6%94%B6%E6%95%9B%E5%AE%B9%E5%B7%AE%E5%A4%9F%E7%B4%A7%E5%90%97%22%7D%0A%20%20T%20--%3E%7C%22%E6%94%BE%E5%BE%97%E5%A4%AA%E6%9D%BE%22%7C%20UNC%5B%22%E6%8B%BF%E5%88%B0%E6%9C%AA%E6%94%B6%E6%95%9B%E7%9A%84%E8%BF%91%E4%BC%BC%E8%A7%A3%22%5D%0A%20%20UNC%20--%3E%20OUT%5B%22%E5%A4%96%E5%B1%82%E7%9F%A9%E6%9D%A1%E4%BB%B6%E5%9C%A8%E9%94%99%E8%A7%A3%E4%B8%8A%E6%B1%82%E5%80%BC%22%5D%0A%20%20OUT%20--%3E%20SE%5B%22%E6%A2%AF%E5%BA%A6%E4%B8%8E%E6%A0%87%E5%87%86%E8%AF%AF%E5%85%A8%E9%94%99%22%5D%0A%20%20T%20--%3E%7C%22%E5%A4%9F%E7%B4%A7%E4%B8%94%E5%A6%82%E5%AE%9E%E8%AE%B0%E5%BD%95%22%7C%20CONV%5B%22%E6%94%B6%E6%95%9B%E8%A7%A3%E5%85%A5%E4%BA%A4%E4%BB%98%2C%20%E5%AE%B9%E5%B7%AE%E5%86%99%E6%98%8E%22%5D%0A%20%20CONV%20--%3E%20OK%5B%22%E5%A4%96%E5%B1%82%E6%8E%A8%E6%96%AD%E5%8F%AF%E4%BF%A1%2C%20%E5%AE%B9%E5%B7%AE%E8%BF%9B%E5%AE%A1%E8%AE%A1%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[n(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=A('<p>不这么做会错在哪：用样本量代替代表性论证；把未收敛的内层解当收敛解传给外层；在向量化都没做的代码上谈分布式。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>分布式系统的原理、数据库与调度的工程细节不在本栏，计算机栏另行处理；这里只冻结接口：经济学要的是分组聚合、逐组回归与参数网格的规模化语义。云上实验的成本控制是治理问题——预算、配额与优先级——收束课排进全景。最后一条边界最常被忘：规模化的终点是可行的识别与推断，不是吞吐量；算得快是为了多验几个设计，不是为了少想一个。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>经济计算的三种大——宽、高频、重数值——瓶颈不同，先定位再动手。</li><li>单机阶梯：向量化、列存分区、多核并行；集群只在语义真是分组聚合时上。</li><li>结构估计的时间在内层不动点：解析雅可比与缓存比扩容有效。</li><li>容差是模型风险：外层矩条件必须在收敛解上求值。</li><li>规模化改成本结构不改统计逻辑：大 \\(N\\) 缩方差，不缩偏差。</li><li>出处：Varian, <em>JEP</em> 2014；Einav and Levin, <em>Science</em> 2014；Athey 2018；Berry, Levinsohn and Pakes, <em>Econometrica</em> 1995。</li></ul>',5))])}const F=i(c,[["render",d]]);export{u as __pageData,F as default};
